  str_n31_1_name_desc = "/",
  str_n31_2_name_desc = "Schwartz tiene una cita con el enviado de Northland, Jakine, que llega para reponer el Cristal de la Eterna Memoria con agua del Lago Espejo. Usted y Mia tropezar con esta escena por casualidad.",
  str_n31_3_name_desc = "Los dos descubren que pueden haber entrado en la historia registrada por el Cristal de la Memoria Eterna, pero la situación parece inestable...",
  str_n31_4_name_desc = "Usted y Mia no son los únicos atraídos hacia el Cristal de la Memoria Eterna. En un rincón distante de Lumopolis, otros dos individuos también se encuentran con los Eclipsites.",
  str_n31_5_name_desc = "Sigues a los guardias hasta la puerta de Lumopolis y te sorprendes al encontrar un grupo de Eclipsites al acecho en medio de las mercancías entrantes.",
  str_n31_6_name_desc = "/",
  str_n31_7_name_desc = "Schwartz pregunta Mia para unirse al duelo delante de todos. No queriendo simplemente montar un espectáculo, Mia le pide a su oponente que no se contenga.",
  str_n31_8_name_desc = "La increíble actuación de Mia en el duelo le gana una ola de aplausos. Parece que el duelo va a durar bastante.",
  str_n31_9_name_desc = "Durante el duelo, Mia accidentalmente rompe una caja de madera a su alrededor. Poco sabe ella que hay sorpresas escondidas en el interior...",
  str_n31_10_name_desc = "A medida que la plaza central desciende hacia el caos, la gente huye en todas direcciones. En medio de la conmoción, Sharona da un paso adelante, ofreciéndose a ayudar Jakine en localizarte y Mia.",
  str_n31_11_name_desc = "Más Eclipsites emergen de los rincones de Lumopolis, mientras un grupo de guardias se acerca de manera ordenada. Sin embargo, se hace evidente que no son refuerzos.",
  str_n31_12_name_desc = "/",
  str_n31_13_name_desc = "Siguiente Schwartz, usted y Mia llega al escondite de los rebeldes, donde te encuentras con soldados rebeldes acechando en las sombras, como era de esperar.",
  str_n31_14_name_desc = "Apoyados contra la pared, los soldados rebeldes están preparados para la pelea, y parece que también han convocado a un aliado formidable...",
  str_n31_15_name_desc = "/",
  str_n31_16_name_desc = "Schwartz lanza una mirada significativa a Joshua, rebosante de palabras no pronunciadas. Pero su cena a la luz de las velas se interrumpe abruptamente...",
  str_n31_1_name_desc_long = "Con un costoso traje alquilado, se prepara para asistir a la fiesta de celebración de Schwartz Día de la Familia en Lumópolis. Justo cuando estás a punto de partir, el esperado Northland Messenger no llega, sino que te cruzas con Mia. Ella parece completamente diferente y, con timidez, confía en su deseo de encontrar a su familia.",
  str_n31_2_name_desc_long = "El enviado de Northland, Jakine, repone el Cristal de la Memoria Eterna con agua del Lago Espejo. Al escuchar que la persona que una vez activó el Cristal de la Memoria Eterna ya no está en este mundo, Jakine decide encontrar otra manera de ayudar Schwartz entrar en el reino del Cristal una vez más.",
  str_n31_3_name_desc_long = "Usted y Mia son traídos al mundo del Cristal de la Memoria Eterna, pero el resto de ustedes está desaparecido. A medida que explora, se da cuenta de que ha tropezado con el Schwartz Celebración del Día de la Familia de hace doce años. Sorprendentemente, las personas que te rodean se dirigen Mia como la Princesa Verónica con gran reverencia.",
  str_n31_4_name_desc_long = "A pesar de las objeciones de Jakine, Caleb, al darse cuenta de que ha entrado en el Cristal de la Memoria Eterna, toma la decisión de proceder solo.",
  str_n31_5_name_desc_long = "Caleb conoce a su hermana en la mansión de Schwartz, pero ella no lo reconoce después de doce años. Mientras tanto, tú y Mia ayuda a los guardias en la puerta de Lumopolis contra un grupo de Eclipsites escondidos entre la carga, donde te presentan al Caballero Capitán Mime Kartima.",
  str_n31_6_name_desc_long = "Las dudas de Mia se desvanecen cuando ve a su madre, Joshua y su hermana. Carleen. Los sueños vívidos en su mente ya no son sus propias ilusiones. Mia finalmente acepta la verdad de que una vez fue la princesa Verónica.",
  str_n31_7_name_desc_long = "Una mujer borracha se burla de las habilidades de adivinación de Jakine y te localiza a ti y a Mia para Jakine durante el desfile de carruajes. Sin embargo, debido a la distancia, no puedes ver Jakine. Después del desfile, Schwartz insiste en que Mia únete al ritual del duelo, y es entonces cuando ves la determinación inquebrantable de Mia por primera vez.",
  str_n31_8_name_desc_long = "Impulsado por su intención de robar el Cristal de la Memoria Eterna del mundo, Caleb incapacita rápidamente a los guardias de la mansión de Schwartz. Mientras tanto, Jakine se ve obligada a creer que la mujer aparentemente discreta que tiene delante es de hecho su propia madre.",
  str_n31_9_name_desc_long = "Dentro del Cristal de la Memoria Eterna, Schwartz finalmente te conoce. Él te culpa por dejar Mia correr el riesgo de participar en el duelo. Sin embargo, como ves Mia a punto de ganar el duelo, no puedes entender porque Schwartz sigue tan preocupada.",
  str_n31_10_name_desc_long = "Schwartz quiere huir del área infestada de Eclipsite con Mia y tú, pero él está retenido por Schwartz desde dentro del Cristal de la Memoria Eterna. A pesar de la brecha de apenas doce años entre los dos Schwartz, ya no se parecen en nada.",
  str_n31_11_name_desc_long = "Jakine finalmente se reencuentra contigo, pero la situación que se avecina parece sombría. Los eclipses continúan emergiendo y otra facción de rebeldes se encuentra ante ti. Finalmente queda claro por qué Schwartz ha sido inflexible en mantener Mia y tu lejos de la Schwartz de este mundo",
  str_n31_12_name_desc_long = "A pesar de ser apuñalado, Schwartz desde dentro del Cristal de la Memoria Eterna logra defenderse de los rebeldes con la ayuda de la multitud. Se hace evidente que Mime Kartima es la mente maestra detrás de la rebelión. Mientras Schwartz desea proteger Mia al revivir esa historia, su determinación de descubrir la verdad permanece inquebrantable.",
  str_n31_13_name_desc_long = "Al descubrir el escondite de los rebeldes, Schwartz dentro del Cristal de la Memoria Eterna instruye Mia para lograr la victoria por cualquier medio necesario, una postura que no puede respaldar. Mientras tanto, el otro Schwartz expresa su esperanza de que pueda encontrar un camino alternativo.",
  str_n31_14_name_desc_long = "Mime Kartima convoca a un dragón volador para que lo ayude, pero Schwartz notablemente lucha contra el dragón solo. Al final, Schwartz pone fin a la rebelión, como era de esperar.",
  str_n31_15_name_desc_long = "Con el período más peligroso detrás de ellos, Schwartz finalmente revela su lado amable rara vez visto. Jakine emplea la magia para restaurar Schwartz a su apariencia juvenil, otorgándole la oportunidad de despedirse como es debido de Joshua, a quien nunca ha podido separar de su corazón.",
  str_n31_16_name_desc_long = "Sin previo aviso, el mundo del Cristal de la Memoria Eterna se desmorona abruptamente en una pequeña isla, con una sombra persiguiéndote sin descanso. Mientras suena la campana de medianoche, la pregunta apremiante persiste: ¿saldrán todos ilesos del Cristal de la Memoria Eterna?",
  str_n31_h1_name = "H1 - Curar",
  str_n31_h2_name = "H2 - Guardián",
