  str_n31_h4_name = "H4 - Sacrificio",
  str_n31_h5_name = "H5 - Rescate",
  str_n31_h6_name = "H6 - Disminuir",
  str_n31_h7_name = "EX1 - Bombardeo",
  str_n31_h8_name = "EX2 - Obstáculo",
  str_n31_h9_name = "EX3 - Conquista",
  str_n31_h10_name = "EX4 - Mata",
  str_n31_h11_name = "EX5 - Embestida",
  str_n31_h12_name = "EX6 - Vanguardia",
  str_n31_h1_name_desc = "En el camino, los obstáculos abundan como espinas. Pero con determinación inquebrantable, podemos curar rápidamente las heridas en el camino.",
  str_n31_h2_name_desc = "Los ataques normales no funcionarán. Es hora de dar rienda suelta a sus poderosas habilidades.",
  str_n31_h3_name_desc = "Si no puede avanzar desde el frente, puede valer la pena intentar una aproximación lateral, incluso si eso significa tomar un largo desvío...",
  str_n31_h4_name_desc = "El calor abrasador intensifica la batalla, lo que representa un mayor riesgo para todos los involucrados.",
  str_n31_h5_name_desc = "Manténgase atento a las trampas, pero también recuerde aprovechar cualquier oportunidad que puedan presentar.",
  str_n31_h6_name_desc = "Los ataques del enemigo vienen como olas implacables. Esfuérzate por debilitarlo y derrotarlo antes del próximo ataque.",
  str_n31_h7_name_desc = "A veces, no es el jefe en sí mismo el que resulta letal, sino los secuaces que acechan cerca.",
  str_n31_h8_name_desc = "Luchar en este terreno traicionero no es tarea fácil. Tal vez puedas cambiar las tornas y explotar las vulnerabilidades del enemigo a tu favor.",
  str_n31_h9_name_desc = "La fuerza del enemigo se intensifica en la etapa decisiva de la batalla. Derrótalos rápidamente para asegurar la victoria.",
  str_n31_h10_name_desc = "Aprovecha la ventaja eliminando rápidamente a los enemigos justo después de que aparezcan para cambiar el rumbo a tu favor.",
  str_n31_h11_name_desc = "Debes evitar que los interminables refuerzos del enemigo se unan a la batalla.",
  str_n31_h12_name_desc = "Potente y rápido, el oponente parece imbatible. Solo con determinación puedes sobrevivir.",
  str_n31_blackbox_title = "Parto Precario",
  str_n31_blackbox_intro = "Los eclipses se vuelven más frecuentes en el continente Astra, lo que representa una amenaza creciente para las rutas de entrega. A medida que resurgen los Colosos, Caelestites y sus compañeros se vuelven más proactivos. Ciertas facciones reconocen las notables habilidades de vuelo y las maniobras de largo alcance del Colossus, confiándoles envíos especiales y arriesgados.",
  str_n31_activity_blackbox_intro_title = "Información de juego de entrega precaria",
  str_n31_activity_blackbox_intro_head_1 = "Modo Caja de Pandora",
  str_n31_activity_blackbox_intro_body_1 = [[
1. La entrega precaria se incluye en el modo Caja de Pandora
2. El modo Caja de Pandora consta de 6 etapas, cada una de las cuales comprende 2 o 3 subetapas.
3. Las etapas de Pandora's Box cuentan con un mecanismo de desbloqueo. Completar cualquier subetapa dentro de una etapa de Pandora's Box desbloquea la siguiente etapa.
4. No hay un mecanismo de desbloqueo entre las subetapas, por lo que puedes desafiarlos libremente.
5. Se deben desplegar diferentes Aurorianos al desafiar subetapas dentro de la misma etapa de Pandora's Box.]],
  str_n31_activity_blackbox_intro_head_2 = "Trofeo de desafío",
  str_n31_activity_blackbox_intro_body_2 = "1. Cada etapa de Pandora's Box tiene de 3 a 5 trofeos de desafío, y los diferentes trofeos de desafío tienen diferentes condiciones de desafío.\n2. Los navegadores deben completar el número requerido de etapas de waypoints con las alineaciones requeridas de acuerdo con el contenido del Trofeo para obtener los Trofeos y recompensas correspondientes.\n3.Como no hay orden entre los Trofeos, los Navegantes pueden desafiar cada Trofeo varias veces.\n4. Una vez que se obtiene un trofeo de desafío, permanecerá incluso cuando se reinicie la formación del escenario.",
